  "inlineSchema": "// Prisma schema for fscrm — a Feishu-integrated CRM.\n//\n// 领域词汇对齐根目录 GLOSSARY.md：客户、联系人、线索、商机、销售阶段、\n// 跟进、负责人、客户生命周期等。\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n/// 客户等级：对客户价值或重要程度的分级。\nenum CustomerLevel {\n  HIGH\n  MEDIUM\n  LOW\n}\n\n/// CRM 用户角色：普通负责人或管理员。\nenum UserRole {\n  OWNER // 普通负责人，仅能访问自己负责的业务对象\n  ADMIN // 管理员，可访问与管理全部业务对象\n}\n\n/// 销售阶段：商机在成交路径上所处的阶段。\nenum OpportunityStage {\n  CONTACT // 初步接触\n  NEED_CONFIRM // 需求确认\n  QUOTE // 报价\n  NEGOTIATE // 谈判\n  WON // 赢单\n  LOST // 输单\n}\n\n/// 线索状态：线索在培育路径上的状态。\nenum LeadStatus {\n  NEW // 新线索\n  FOLLOWING // 跟进中\n  CONVERTED // 已转化\n  INVALID // 无效\n}\n\n/// 跟进方式：跟进时使用的沟通渠道。\nenum FollowUpMode {\n  CALL // 电话\n  MEETING // 面谈\n  EMAIL // 邮件\n  IM // 即时消息\n  OTHER // 其他\n}\n\n/// 部门：由飞书通讯录同步而来。\nmodel Department {\n  id                 String  @id @default(uuid())\n  /// 飞书部门 ID，作为同步的唯一键。\n  feishuDepartmentId String  @unique\n  /// 开放部门 ID。\n  openDepartmentId   String?\n  name               String\n  /// 父部门在 CRM 中的 ID。\n  parentId           String?\n  /// 部门负责人（飞书用户 ID）。\n  leaderFeishuUserId String?\n  memberCount        Int?\n\n  users User[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"departments\")\n}\n\n/// CRM 用户（负责人）：可绑定飞书用户，是消息接收与操作归属的主体。\nmodel User {\n  id            String      @id @default(uuid())\n  name          String\n  email         String?\n  avatarUrl     String?\n  /// 飞书开放 ID，用于与飞书用户稳定匹配（身份绑定）。\n  feishuOpenId  String?     @unique\n  feishuUnionId String?\n  feishuUserId  String?\n  /// 角色：普通负责人或管理员；新用户默认按普通负责人处理。\n  role          UserRole    @default(OWNER)\n  /// 所属部门。\n  departmentId  String?\n  department    Department? @relation(fields: [departmentId], references: [id])\n\n  customers     Customer[]\n  opportunities Opportunity[]\n  leads         Lead[]\n  followUps     FollowUp[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"users\")\n}\n\n/// 客户：CRM 的核心业务对象。\nmodel Customer {\n  id       String        @id @default(uuid())\n  name     String\n  level    CustomerLevel @default(MEDIUM)\n  industry String?\n  phone    String?\n  email    String?\n  address  String?\n  remark   String?\n  /// 负责人，对应 User。\n  ownerId  String?\n  owner    User?         @relation(fields: [ownerId], references: [id])\n\n  contacts      Contact[]\n  opportunities Opportunity[]\n  followUps     FollowUp[]\n  quotations    Quotation[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"customers\")\n}\n\n/// 联系人：与客户关联的具体人员。\nmodel Contact {\n  id         String   @id @default(uuid())\n  customerId String\n  customer   Customer @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  name       String\n  position   String?\n  phone      String?\n  email      String?\n  remark     String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"contacts\")\n}\n\n/// 线索：尚未明确成交意向的原始客户信息。\nmodel Lead {\n  id           String     @id @default(uuid())\n  name         String\n  /// 线索来源：表单、转介绍、市场活动等。\n  source       String?\n  status       LeadStatus @default(NEW)\n  /// 负责人，对应 User。\n  ownerId      String?\n  owner        User?      @relation(fields: [ownerId], references: [id])\n  contactPhone String?\n  contactEmail String?\n  remark       String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"leads\")\n}\n\n/// 商机：已识别出明确意向、进入销售流程的销售机会。\nmodel Opportunity {\n  id                String           @id @default(uuid())\n  customerId        String\n  customer          Customer         @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  name              String\n  stage             OpportunityStage @default(CONTACT)\n  /// 预计成交金额。\n  amount            Float?\n  /// 预计成交日期。\n  expectedCloseDate DateTime?\n  /// 负责人，对应 User。\n  ownerId           String?\n  owner             User?            @relation(fields: [ownerId], references: [id])\n  remark            String?\n\n  followUps  FollowUp[]\n  quotations Quotation[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"opportunities\")\n}\n\n/// 跟进记录：对某次跟进的时间、方式、内容与下一步的结构化记录。\nmodel FollowUp {\n  id             String       @id @default(uuid())\n  /// 关联的客户；跟进可挂在客户或商机下，二者至少有一个。\n  customerId     String?\n  customer       Customer?    @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  /// 关联的商机。\n  opportunityId  String?\n  opportunity    Opportunity? @relation(fields: [opportunityId], references: [id], onDelete: Cascade)\n  /// 跟进人，对应 User。\n  ownerId        String?\n  owner          User?        @relation(fields: [ownerId], references: [id])\n  mode           FollowUpMode\n  content        String\n  /// 下一步计划跟进时间。\n  nextFollowUpAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"follow_ups\")\n}\n\n/// 报价状态：报价在确认路径上所处的状态。\nenum QuotationStatus {\n  DRAFT // 草稿\n  CONFIRMED // 已确认\n  CANCELLED // 已取消\n}\n\n/// 报价：针对商机向客户提出的价格方案；金额由报价条目汇总。\nmodel Quotation {\n  id            String          @id @default(uuid())\n  customerId    String\n  customer      Customer        @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  opportunityId String\n  opportunity   Opportunity     @relation(fields: [opportunityId], references: [id], onDelete: Cascade)\n  status        QuotationStatus @default(DRAFT)\n  /// 金额：始终由 items 的数量乘以单价汇总维护。\n  amount        Float           @default(0)\n  items         QuotationItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"quotations\")\n}\n\n/// 报价条目：报价中的单项名称、数量与单价。\nmodel QuotationItem {\n  id          String    @id @default(uuid())\n  quotationId String\n  quotation   Quotation @relation(fields: [quotationId], references: [id], onDelete: Cascade)\n  name        String\n  quantity    Int\n  unitPrice   Float\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"quotation_items\")\n}\n",
